create table users (id uuid primary key default gen_random_uuid(), name text not null, email text not null unique, password_hash text not null, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table user_roles (user_id uuid not null references users(id) on delete restrict, role text not null check (role in ('ADMIN','SUPERVISOR','STAFF','CUSTOMER_SERVICE','DOCUMENT_ASSISTANT')), primary key(user_id,role));
create table tickets (id uuid primary key default gen_random_uuid(), context_kind text not null check (context_kind in ('GENERAL','EVENT','CUSTOMS_JOB')), event_id uuid references events(id) on delete restrict, customs_job_id uuid references customs_jobs(id) on delete restrict, assignee_id uuid references users(id) on delete restrict, title text not null, description text, priority text not null check(priority in ('NORMAL','URGENT')) default 'NORMAL', status text not null check(status in ('TODO','IN_PROGRESS','DONE','CANCELLED')) default 'TODO', outcome text, created_by_user_id uuid references users(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check ((context_kind='GENERAL' and event_id is null and customs_job_id is null) or (context_kind='EVENT' and event_id is not null and customs_job_id is null) or (context_kind='CUSTOMS_JOB' and customs_job_id is not null and event_id is null)), check ((status='DONE' and char_length(trim(outcome))>0) or (status<>'DONE' and outcome is null)));
create table ticket_activities (id uuid primary key default gen_random_uuid(), ticket_id uuid not null references tickets(id) on delete restrict, kind text not null, actor_user_id uuid references users(id) on delete restrict, summary text not null, occurred_at timestamptz not null default now());
create table ticket_comments (id uuid primary key default gen_random_uuid(), ticket_id uuid not null references tickets(id) on delete restrict, author_user_id uuid not null references users(id) on delete restrict, body text not null check(char_length(trim(body))>0), created_at timestamptz not null default now());
